import { describe, it, expect } from "vitest";
import { createArcRotateCamera, attachControl } from "@babylonjs/lite";

function fakeCanvas() {
    const listeners = new Map<string, Array<(e: any) => void>>();
    const canvas: any = {
        addEventListener(t: string, h: (e: any) => void) {
            if (!listeners.has(t)) listeners.set(t, []);
            listeners.get(t)!.push(h);
        },
        removeEventListener() {},
        setPointerCapture() {},
        releasePointerCapture() {},
    };
    const fire = (t: string, e: any) => {
        for (const h of listeners.get(t) ?? []) h({ preventDefault() {}, ...e });
    };
    return { canvas, fire };
}

const snap = (c: any) => ({ alpha: c.alpha, beta: c.beta, radius: c.radius });

describe("probe: no scene", () => {
    it("drag", () => {
        const cam = createArcRotateCamera(1, 1, 10, { x: 0, y: 0, z: 0 } as any);
        const { canvas, fire } = fakeCanvas();
        attachControl(cam, canvas);
        const before = snap(cam);
        fire("pointerdown", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 100, clientY: 100 });
        fire("pointermove", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 160, clientY: 140 });
        fire("pointerup", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 160, clientY: 140 });
        console.log("DRAG", JSON.stringify(before), JSON.stringify(snap(cam)), cam.inertialAlphaOffset, cam.inertialBetaOffset);
        expect(snap(cam)).toEqual(before);
    });
    it("wheel", () => {
        const cam = createArcRotateCamera(1, 1, 10, { x: 0, y: 0, z: 0 } as any);
        const { canvas, fire } = fakeCanvas();
        attachControl(cam, canvas);
        const before = snap(cam);
        fire("wheel", { deltaY: 120 });
        console.log("WHEEL", JSON.stringify(before), JSON.stringify(snap(cam)), cam.inertialRadiusOffset);
        expect(snap(cam)).toEqual(before);
    });
    it("pinch", () => {
        const cam = createArcRotateCamera(1, 1, 10, { x: 0, y: 0, z: 0 } as any);
        const { canvas, fire } = fakeCanvas();
        attachControl(cam, canvas);
        const before = snap(cam);
        const t1 = { identifier: 1, clientX: 100, clientY: 100 };
        const t2 = { identifier: 2, clientX: 200, clientY: 100 };
        fire("touchstart", { changedTouches: [t1, t2] });
        fire("touchmove", { changedTouches: [{ identifier: 2, clientX: 300, clientY: 100 }] });
        console.log("PINCH", JSON.stringify(before), JSON.stringify(snap(cam)));
        expect(snap(cam)).not.toEqual(before);
    });
});
